1	# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
2	# CREATE A IAM POLICIES FOR EKS SERVICEACCOUNT
3	# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
4	
5	# ---------------------------------------------------------------------------------------------------------------------
6	# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
7	# ---------------------------------------------------------------------------------------------------------------------
8	
9	terraform {
10	  required_version = "~> 1.0"
11	
12	  required_providers {
13	    aws = {
14	      source  = "hashicorp/aws"
15	      version = "~> 6.0"
16	    }
17	  }
18	}
19	
20	# ---------------------------------------------------------------------------------------------------------------------
21	# CREATE A TERRAFORM RESOURCE
22	# ---------------------------------------------------------------------------------------------------------------------
23	
24	data "aws_iam_policy_document" "policy_doc" {
25	  count = length(var.policy_statements) > 0 ? 1 : 0
26	
27	  dynamic "statement" {
28	    for_each = var.policy_statements
29	    content {
30	      sid           = statement.value.sid
31	      effect        = statement.value.effect
32	      actions       = statement.value.actions
33	      not_actions   = statement.value.not_actions
34	      resources     = statement.value.resources
35	      not_resources = statement.value.not_resources
36	      dynamic "principals" {
37	        for_each = statement.value.principals
38	        content {
39	          identifiers = principals.value.identifiers
40	          type        = principals.value.type
41	        }
42	      }
43	      dynamic "not_principals" {
44	        for_each = statement.value.not_principals
45	        content {
46	          identifiers = not_principals.value.identifiers
47	          type        = not_principals.value.type
48	        }
49	      }
50	      dynamic "condition" {
51	        for_each = statement.value.conditions
52	        content {
53	          test     = condition.value.test
54	          variable = condition.value.variable
55	          values   = condition.value["values"]
56	        }
57	      }
58	    }
59	  }
60	}
61	
62	resource "aws_iam_policy" "policy" {
63	  count = length(var.policy_statements) > 0 ? 1 : 0
64	
65	  name   = var.role_name
66	  policy = data.aws_iam_policy_document.policy_doc[0].json
67	  path   = var.policy_path
68	  tags   = var.tags
69	}
70	
71	data "aws_iam_policy_document" "assume_doc" {
72	  dynamic "statement" {
73	    for_each = toset(var.assume_role_entities)
74	    content {
75	      actions = ["sts:AssumeRoleWithWebIdentity"]
76	      condition {
77	        test     = statement.value["test"]
78	        variable = format("%s:sub", statement.value["identity_provider_issuer"])
79	        values = [
80	          format("system:serviceaccount:%s:%s", statement.value["namespace"], statement.value["service_account_name"])
81	        ]
82	      }
83	      condition {
84	        test     = statement.value["test"]
85	        variable = format("%s:aud", statement.value["identity_provider_issuer"])
86	        values = [
87	          "sts.amazonaws.com"
88	        ]
89	      }
90	      principals {
91	        type        = "Federated"
92	        identifiers = [statement.value["identity_provider_arn"]]
93	      }
94	    }
95	  }
96	}
97	
98	
99	resource "aws_iam_role" "role" {
100	  assume_role_policy = data.aws_iam_policy_document.assume_doc.json
101	  name               = var.role_name
102	  tags               = var.tags
103	}
104	
105	resource "aws_iam_role_policy_attachment" "attachment" {
106	  count = length(var.policy_statements) > 0 ? 1 : 0
107	
108	  policy_arn = aws_iam_policy.policy[0].arn
109	  role       = aws_iam_role.role.name
110	}
111

1	output "iam_role_arn" {
2	  description = "The ARN of the created role"
3	  value       = aws_iam_role.role.arn
4	}
5	
6	output "iam_role_name" {
7	  description = "The ARN of the created role"
8	  value       = aws_iam_role.role.name
9	}
10	
11	output "iam_policy_arn" {
12	  description = "The ARN of the created policy"
13	  value       = length(var.policy_statements) > 0 ? aws_iam_policy.policy[0].arn : null
14	}
15	
16	output "iam_policy_name" {
17	  description = "The ARN of the created policy"
18	  value       = length(var.policy_statements) > 0 ? aws_iam_policy.policy[0].name : null
19	}
20	
21
